"""Deterministic Russian reporting; no inputs are sent back to replay."""
from io_utils import read_csv

def build(out,summary,monthly,transitions,comparison,independent):
 def fmt(v):return f'{v:.6f}' if isinstance(v,float) else str(v)
 def table(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(fmt(x) for x in row)+' |\n' for row in rows)
 def pair(period):return [next(x for x in summary if x['variant']==mode and x['period']==period) for mode in ('CONTROL','BE1')]
 a,b=pair('2023_2024');c=comparison['2023_2024'];cohort=read_csv(out/'ORIGINAL_GE_2R_BY_YEAR.csv')[0]
 lines=['# T3/M15 SESSION T1 — единственный BE1 AFTER +1R\n',
 'Полный причинный replay development 2023–2024. CONTROL `T3_M15_T1_TRAIL35_N4_R15`, NEXT_OPEN, Initial Stop 2 ATR, trailing 3.5 ATR, FULL N4. Никаких подтверждений PR563 или других альтернатив.\n',
 '## Основное сравнение\n']
 metrics=[('CLOSED','CLOSED'),('OPEN на конце','OPEN_at_period_end'),('Отрицательных CLOSED месяцев','CLOSED_R_negative_months'),('Отрицательных MTM месяцев','MTM_R_negative_months'),('Сумма отрицательных CLOSED месяцев, R','CLOSED_R_negative_sum'),('Сумма отрицательных MTM месяцев, R','MTM_R_negative_sum'),('Худший CLOSED месяц','CLOSED_R_worst_month'),('Худший CLOSED месяц, R','CLOSED_R_worst_R'),('Худший MTM месяц','MTM_R_worst_month'),('Худший MTM месяц, R','MTM_R_worst_R'),('CLOSED-R DD','CLOSED_R_DD'),('Close-mark MTM-R DD','MTM_R_DD'),('Gross PF','gross_PF'),('Gross R','gross_R'),('Expectancy R','expectancy_R'),('Победители >=2R: количество','winner_ge_2R_count'),('Победители >=2R: вклад R','winner_ge_2R_R')]
 lines.insert(1,'**Механизм неудачен. Остановиться без следующего порога.** Сокращение отрицательных trailing-выходов оплачено потерей крупных победителей и ухудшением месячной стабильности. Отрицательных CLOSED месяцев 6 → 7, в 2024 CLOSED/MTM 3/3 → 5/4. Фиксированная исходная когорта >=2R потеряла 51.372926R (16.15%); 10 её сделок стали неположительными. Суммарный Gross R снизился на 24.059722R. Улучшение MTM DD не компенсирует провал основной цели.\n')
 lines.append(table(['Метрика','CONTROL','BE1'],[(label,a[key],b[key]) for label,key in metrics]))
 lines.extend(['\n## 2023 и 2024 отдельно\n',table(['Год','Модель','CLOSED / OPEN','Gross PF','Gross R','− CLOSED / MTM','CLOSED / MTM DD','>=2R: число / R'],[(year,x['variant'],str(x['CLOSED'])+' / '+str(x['OPEN_at_period_end']),x['gross_PF'],x['gross_R'],str(x['CLOSED_R_negative_months'])+' / '+str(x['MTM_R_negative_months']),fmt(x['CLOSED_R_DD'])+' / '+fmt(x['MTM_R_DD']),str(x['winner_ge_2R_count'])+' / '+fmt(x['winner_ge_2R_R'])) for year in ('2023','2024') for x in pair(year)])])
 lines.extend(['\n## Все календарные месяцы МСК\n',table(['Месяц','CONTROL CLOSED','BE1 CLOSED','CONTROL MTM','BE1 MTM'],[(month,*[next(r for r in monthly if r['month']==month and r['variant']==mode)[basis] for basis in ('CLOSED_R','MTM_R') for mode in ('CONTROL','BE1')]) for month in sorted({r['month'] for r in monthly})])])
 changes=[r for r in transitions if r['sign_changed']]
 lines.append('\nСмена знаков:\n\n'+table(['Месяц','База','CONTROL R','BE1 R'],[(r['month'],r['basis'],r['CONTROL_R'],r['BE1_R']) for r in changes]))
 lines.append('\n## Отрицательные trailing и ранние выходы\n')
 lines.append(f"В исходной сопоставляемой когорте {c['CONTROL_negative_trailing']} отрицательных trailing-выходов. Предотвращено {c['negative_trailing_prevented']} (BE1 CLOSED >=0): {fmt(c['prevented_trailing_CONTROL_R'])}R → {fmt(c['prevented_trailing_BE1_R'])}R. Остались отрицательными {c['negative_trailing_still_negative']}, пропущены {c['negative_trailing_missed']}, OPEN {c['negative_trailing_OPEN']}. Пропуски не названы спасёнными сделками.\n")
 lines.append(table(['Модель','Период','Отрицательных trailing','Их R','Всех отрицательных','Нулевых','BE stop raises','BE negative gap exits'],[(r['variant'],r['exit_or_event_year'],r['negative_trailing_count'],r['negative_trailing_R'],r['negative_trades'],r['zero_trades'],r['BE1_stop_raises'],r['BE1_source_negative_gap_exits']) for r in read_csv(out/'MECHANISM_SUMMARY.csv')]))
 lines.append(f"\nРаньше закрылись {c['profitable_closed_earlier']} исходных прибыльных сделок: {fmt(c['early_profitable_CONTROL_R'])}R → {fmt(c['early_profitable_BE1_R'])}R. Всего исходных прибыльных → неположительные: {c['profitable_to_nonpositive']}; пропущенных прибыльных: {c['missed_profitable']}; прибыльных → OPEN: {c['profitable_to_OPEN']}. По каждой сделке сохранены сроки и исходы в EARLY_PROFITABLE_EXITS.csv / TRADE_COMPARISON.csv.\n")
 lines.append('\n## Исходная фиксированная когорта >=2R\n')
 lines.append(table(['Signal-year','Исходных','CONTROL R','Сохранили >=2R','Пропущены','Неположительные','OPEN','Раньше закрыты','BE1 CLOSED R'],[(r['signal_year'],r['original_ge2R_count'],r['CONTROL_R'],r['retained_ge2R'],r['skipped'],r['to_nonpositive'],r['OPEN'],r['closed_earlier'],r['BE1_CLOSED_contribution_R']) for r in read_csv(out/'ORIGINAL_GE_2R_BY_YEAR.csv')]))
 lines.append('Исходные 74 >=2R дают 318.179969R; полный набор BE1 — 68 и 285.829724R (−10.17% вклада). Фиксированная исходная когорта BE1 даёт 266.807042R (−16.15%); 64 сохранили >=2R, 10 стали неположительными. Ещё четыре >=2R победителя появились среди новых входов. Полный набор победителей BE1 в основной таблице включает новые сделки; эта фиксированная когорта сохраняет исходные signal identifiers. Пропуски не получают вымышленного CLOSED-исхода; сумма когорты включает только фактически CLOSED.\n')
 lines.append('\n## Занятость и атрибуция\n')
 lines.append(f"Общих входов {c['common_signals']}, пропущенных CONTROL {c['missed_control_entries']}, новых BE1 {c['new_BE1_entries']}. ΔR общих CLOSED {fmt(c['matched_delta_R'])}, новых CLOSED {fmt(c['new_entries_R'])}, исключённых CONTROL CLOSED {fmt(c['missed_entries_CONTROL_R'])}. Их сумма matched + new − missed = {fmt(c['matched_delta_R']+c['new_entries_R']-c['missed_entries_CONTROL_R'])}R. Все общие входы сохраняют исходные entry/Initial Stop/R0. Готовые сделки не фильтруются.\n")
 lines.append('\n## Причинность и проверка\n')
 lines.append('На каждой свече: NEXT_OPEN, действующий Stop и adverse Open gap, затем только при выживании обычный trailing и BE1. +1R от фактического входа использует immutable первоначальный риск; High/Low exit-bar не используются для новых Stop/MFE. Стоп не пересчитывается задним числом. Новый Stop работает на следующей наблюдаемой свече, включая gaps; BE может исполниться с убытком на gap. Более сильный trailing сохраняется.\n')
 lines.append(f"Полный исторический CONTROL PR518/560: 1114 CLOSED / 356 INITIAL_STOP, 473218 полей; независимый полный scalar CONTROL 450938 полей. Development дополнительно PR562 и PR563. Отдельный scalar verifier BE1/CONTROL с streaming features: {independent['rows']} строк, {independent['fields']} полей, max error {independent['max_abs_error']}; fresh CSV/Decimal статистика {independent['independent_statistics']['fresh_CSV_Decimal_fields']} полей. Synthetic contracts, prefix invariance и future-suffix perturbation — PASS. Подробные квитанции AUDIT.json / INDEPENDENT_VERIFICATION.json. После финального freeze три свежих полных процесса сравниваются direct bytes и SHA256 в REPEATABILITY.json.\n")
 lines.append('Независимость алгоритмическая, тем же автором. Внешний human/отдельный агентский аудит NOT_PERFORMED; это не внешнее одобрение.\n')
 lines.append('\n## Покрытие, денежные границы и прежний опыт\n')
 lines.append('МСК Close timestamps; исходный entry_time — signal Close (=следующий смежный Open timestamp), execution_bar_close дан отдельно. Начало GLDRUBF 11 июля и IMOEXF 14 ноября 2023 означает PARTIAL_N4; NO_DATA не трактуется как нулевой инструментальный результат. Никаких синтетических gaps, принудительных закрытий или годовых перезапусков. CLOSED-метрики года по exit-year, исходные когорты по signal-year; MTM переносит unrealized через месяц/год. MTM — сумма последнего наблюдаемого Close-mark по инструментам с forward carry на объединённой шкале; это не intrabar/денежная DD. CLOSED DD сохраняет frozen сортировку exit time / instrument / trade_id.\n')
 lines.append('2025–2026 читаются только изолированной ретроспективной сверкой неизменного CONTROL, не альтернативой/настройкой и не новым независимым OOS. PR496 S2 использовал другие BASELINE/OPTIMIZED сборки и SIGNAL_CLOSE: там убытки сокращались ценой победителей (OPTIMIZED R 178.720 → 163.790; 11 исходных >=2R → неположительные). Эти опубликованные округлённые числа приведены только для сравнения; старый replay не запускался и не импортировался. PR563 — только источник CONTROL и контекста; подтверждение не комбинировалось.\n')
 lines.append('Gross без расходов. Нормированная чувствительность задаётся отдельно --round-trip-cost-R и --round-trip-slippage-R; это не тариф FINAM и не executable Net. Отсутствуют исходный капитал/cashflows, датированные ГО, спецификации/tick value и подтверждённые расходы. Денежная исполнимость, Net RUB, integer qty, RUB DD: **NOT_VALIDATED**. Исторические непрерывные стоп-цены не подтверждают tick-grid fill; R15 не превращает сумму R в денежную доходность.\n')
 (out/'REPORT_RU.md').write_text('\n'.join(lines))
